/**
 * Exception thrown when physical hardware entropy cannot be verified.
 */
class InsufficientHardwareEntropyException extends \RuntimeException {}

/**
 * Machine Fingerprint Utility for SizarDev.
 *
 * Extracts stable, hardware-bound physical machine identifiers on Windows
 * (and Linux fallback) to construct a normalized, deterministic Machine Unique ID.
 *
 * Composite Formula:
 *   SHA-256( BIOS_UUID + BaseBoard_Serial + MachineGuid + CPU_ProcessorId )
 * Canonical Format:
 *   SizarDev-POS-XXXX-XXXX-XXXX-XXXX
 */
class MachineFingerprint
{
    private const CACHE_FILE = __DIR__ . '/../../config/.machine_id_cache.json';
    private const CACHE_SALT = 'sizar-pos-tethered-host-seal-salt-v1';
    private static ?string $cachedId = null;
    private static ?array $cachedTelemetry = null;

    /**
     * Computes an environmental host seal tying cache files to this exact physical OS and directory.
     */
    public static function getHostSeal(): string
    {
        $appRoot = realpath(__DIR__ . '/../../') ?: (__DIR__ . '/../../');
        $raw = implode('|', [
            php_uname('s'),
            php_uname('n'),
            php_uname('m'),
            str_replace('\\', '/', $appRoot)
        ]);
        return hash_hmac('sha256', $raw, self::CACHE_SALT);
    }

    /**
     * Returns the canonical machine ID, e.g. "SizarDev-POS-A570-1D92-CDC9-BCB0".
     */
    public static function getMachineId(bool $forceFresh = false): string
    {
        if (self::$cachedId !== null && !$forceFresh) {
            return self::$cachedId;
        }

        if (!$forceFresh && is_file(self::CACHE_FILE)) {
            $cached = @json_decode((string)@file_get_contents(self::CACHE_FILE), true);
            if (is_array($cached) && !empty($cached['machine_id']) && is_array($cached['telemetry'] ?? null)) {
                // Assert Host Environmental Seal to prevent portable cache replay across machines
                $expectedSeal = self::getHostSeal();
                $actualSeal = (string)($cached['host_seal'] ?? '');
                if (!empty($actualSeal) && hash_equals($expectedSeal, $actualSeal)) {
                    self::$cachedId = self::normalizeMachineId((string)$cached['machine_id']);
                    self::$cachedTelemetry = $cached['telemetry'];
                    return self::$cachedId;
                }
            }
        }

        $telemetry = self::getRawTelemetry($forceFresh);

        // Strict Hardware Entropy Invariant: Must possess verified physical hardware parameters
        self::validateHardwareEntropy($telemetry);

        $composite = sprintf(
            'V1|MB:%s|UUID:%s|CPU:%s|GUID:%s',
            $telemetry['baseboard'] ?? '',
            $telemetry['bios_uuid'] ?? '',
            $telemetry['cpu_id'] ?? '',
            $telemetry['os_guid'] ?? ''
        );

        $hash = strtoupper(hash('sha256', $composite));
        self::$cachedId = self::formatMachineId($hash);

        // Persist to disk cache with Host Seal
        self::saveDiskCache();

        return self::$cachedId;
    }

    /**
     * Validates that the extracted telemetry contains genuine physical hardware entropy.
     * Throws InsufficientHardwareEntropyException if hardware cannot be identified.
     */
    public static function validateHardwareEntropy(array $telemetry): void
    {
        $validPoints = 0;

        // Physical Motherboard or Internal Fixed Disk Serial
        if (!empty($telemetry['baseboard']) && !self::isPlaceholderOrLowEntropy($telemetry['baseboard'])) {
            $validPoints += 2;
        }

        // System / BIOS UUID
        if (!empty($telemetry['bios_uuid']) && !self::isPlaceholderOrLowEntropy($telemetry['bios_uuid'])) {
            $validPoints += 2;
        }

        // Windows MachineGuid
        if (!empty($telemetry['os_guid']) && !self::isPlaceholderOrLowEntropy($telemetry['os_guid'])) {
            $validPoints += 1;
        }

        // Must possess at least one high-entropy physical hardware identifier
        if ($validPoints < 2) {
            throw new InsufficientHardwareEntropyException(
                'Insufficient physical hardware entropy detected. Motherboard, BIOS UUID, and disk parameters are unavailable or restricted. ' .
                'Execution in headless environments or sandboxes without verified hardware is prohibited.'
            );
        }
    }

    /**
     * Gathers raw hardware parameters.
     *
     * @return array{platform: string, baseboard: string, bios_uuid: string, cpu_id: string, os_guid: string, is_fallback: bool}
     */
    public static function getRawTelemetry(bool $forceFresh = false): array
    {
        if (self::$cachedTelemetry !== null && !$forceFresh) {
            return self::$cachedTelemetry;
        }

        if (!$forceFresh && is_file(self::CACHE_FILE)) {
            $cached = @json_decode((string)@file_get_contents(self::CACHE_FILE), true);
            if (is_array($cached) && is_array($cached['telemetry'] ?? null) && !empty($cached['machine_id'])) {
                $expectedSeal = self::getHostSeal();
                $actualSeal = (string)($cached['host_seal'] ?? '');
                if (!empty($actualSeal) && hash_equals($expectedSeal, $actualSeal)) {
                    self::$cachedTelemetry = $cached['telemetry'];
                    self::$cachedId = (string)$cached['machine_id'];
                    return self::$cachedTelemetry;
                }
            }
        }

        if (PHP_OS_FAMILY === 'Windows') {
            $data = self::extractWindows();
        } elseif (PHP_OS_FAMILY === 'Darwin') {
            $data = self::extractMac();
        } else {
            throw new InsufficientHardwareEntropyException(
                'Unsupported operating system platform [' . PHP_OS_FAMILY . ']. Sizar POS Pro requires verified physical Windows or macOS workstations.'
            );
        }

        self::$cachedTelemetry = $data;
        return $data;
    }

    private static function saveDiskCache(): void
    {
        if (self::$cachedId !== null && self::$cachedTelemetry !== null) {
            @file_put_contents(self::CACHE_FILE, json_encode([
                'machine_id' => self::$cachedId,
                'telemetry'  => self::$cachedTelemetry,
                'host_seal'  => self::getHostSeal(),
                'cached_at'  => date('Y-m-d H:i:s'),
            ], JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES));
        }
    }

