    private static function extractWindows(): array
    {
        // Single bundled PowerShell script with ProgressPreference suppression and Fixed-Disk filtering
        $psScript = '$ProgressPreference = "SilentlyContinue";
function getHW($c, $p) {
    try { if (Get-Command Get-CimInstance -EA SilentlyContinue) { $v = (Get-CimInstance $c -EA SilentlyContinue | Select-Object -First 1).$p; if ($v) { return [string]$v } } } catch {}
    try { if (Get-Command Get-WmiObject -EA SilentlyContinue) { $v = (Get-WmiObject $c -EA SilentlyContinue | Select-Object -First 1).$p; if ($v) { return [string]$v } } } catch {}
    return ""
}
$mb = getHW "Win32_BaseBoard" "SerialNumber";
if (-not $mb -or ($mb -match "to be filled|none|default|0000")) {
    try {
        $disk = Get-CimInstance Win32_DiskDrive -EA SilentlyContinue | Where-Object { $_.MediaType -match "Fixed" } | Select-Object -First 1;
        if (-not $disk) {
            $disk = Get-CimInstance Win32_DiskDrive -EA SilentlyContinue | Where-Object { $_.InterfaceType -notmatch "USB" } | Select-Object -First 1;
        }
        if (-not $disk) {
            $disk = Get-WmiObject Win32_DiskDrive -EA SilentlyContinue | Where-Object { $_.MediaType -match "Fixed" } | Select-Object -First 1;
        }
        if ($disk -and $disk.SerialNumber) { $mb = [string]$disk.SerialNumber; }
    } catch {}
}
$uuid = getHW "Win32_ComputerSystemProduct" "UUID";
$cpu = getHW "Win32_Processor" "ProcessorId";
$guid = "";
try { $guid = (Get-ItemProperty -Path "HKLM:\SOFTWARE\Microsoft\Cryptography" -Name MachineGuid -EA SilentlyContinue).MachineGuid; } catch {}
Write-Output ("MB:" + [string]$mb.Trim() + "|UUID:" + [string]$uuid.Trim() + "|CPU:" + [string]$cpu.Trim() + "|GUID:" + [string]$guid.Trim());';

        $encoded = base64_encode(iconv('UTF-8', 'UTF-16LE', $psScript));
        $cmd = "powershell -NoProfile -NonInteractive -ExecutionPolicy Bypass -EncodedCommand {$encoded} 2>&1";

        $raw = shell_exec($cmd);
        $baseboard = '';
        $biosUuid = '';
        $cpuId = '';
        $osGuid = '';
        $isFallback = false;

        if ($raw && preg_match('/MB:([^|]*)\|UUID:([^|]*)\|CPU:([^|]*)\|GUID:([^\r\n]*)/i', $raw, $matches)) {
            $baseboard = self::normalize($matches[1] ?? '');
            $biosUuid  = self::normalize($matches[2] ?? '');
            $cpuId     = self::normalize($matches[3] ?? '');
            $osGuid    = self::normalize($matches[4] ?? '');
        } else {
            // Secondary fallback if PowerShell execution was restricted: volume serial + computer name
            $isFallback = true;
            $volOutput = shell_exec('vol C: 2>&1');
            if ($volOutput && preg_match('/Serial Number is\s+([A-Z0-9-]+)/i', $volOutput, $volMatches)) {
                $baseboard = self::normalize($volMatches[1]);
            }
            $osGuid = self::normalize(gethostname() ?: 'UNKNOWN-HOST');
        }

        return [
            'platform'    => 'windows',
            'baseboard'   => $baseboard,
            'bios_uuid'   => $biosUuid,
            'cpu_id'      => $cpuId,
            'os_guid'     => $osGuid,
            'is_fallback' => $isFallback,
        ];
    }

    /**
     * macOS hardware extraction via Apple I/O Kit (ioreg) and sysctl.
     * Guaranteed to extract genuine physical Apple serial and platform UUID.
     */
    private static function extractMac(): array
    {
        $serial = '';
        $uuid = '';
        $cpu = '';
        $model = '';

        // 1. Query Apple IOPlatformExpertDevice for hardware Serial Number and Platform UUID
        if (function_exists('shell_exec')) {
            $ioregOutput = (string) @shell_exec('/usr/sbin/ioreg -rd1 -c IOPlatformExpertDevice 2>/dev/null');
            if (!empty($ioregOutput)) {
                if (preg_match('/"IOPlatformSerialNumber"\s*=\s*"([^"]+)"/', $ioregOutput, $m)) {
                    $serial = trim($m[1]);
                }
                if (preg_match('/"IOPlatformUUID"\s*=\s*"([^"]+)"/', $ioregOutput, $m)) {
                    $uuid = trim($m[1]);
                }
                if (preg_match('/"model"\s*=\s*<"([^"]+)">/', $ioregOutput, $m)) {
                    $model = trim($m[1]);
                }
            }

            // 2. Query CPU / Chipset identifier via sysctl
            $cpuBrand = (string) @shell_exec('/usr/sbin/sysctl -n machdep.cpu.brand_string 2>/dev/null');
            if (empty(trim($cpuBrand))) {
                $cpuBrand = (string) @shell_exec('/usr/sbin/sysctl -n hw.model 2>/dev/null');
            }
            $cpu = trim($cpuBrand);
        }

        return [
            'platform'    => 'darwin',
            'baseboard'   => self::normalize($serial),
            'bios_uuid'   => self::normalize($uuid),
            'cpu_id'      => self::normalize($cpu ?: ($model ?: php_uname('m'))),
            'os_guid'     => self::normalize(gethostname() ?: 'MACOS-HOST'),
            'is_fallback' => false,
        ];
    }

    /**
     * Linux extraction fallback (/etc/machine-id, product_uuid).
     */
    private static function extractLinux(): array
    {
        $machineId = '';
        $biosUuid = '';

        if (@is_file('/etc/machine-id') && @is_readable('/etc/machine-id')) {
            $machineId = trim((string) @file_get_contents('/etc/machine-id'));
        } elseif (@is_file('/var/lib/dbus/machine-id') && @is_readable('/var/lib/dbus/machine-id')) {
            $machineId = trim((string) @file_get_contents('/var/lib/dbus/machine-id'));
        }

        if (@is_file('/sys/class/dmi/id/product_uuid') && @is_readable('/sys/class/dmi/id/product_uuid')) {
            $biosUuid = trim((string) @file_get_contents('/sys/class/dmi/id/product_uuid'));
        }

        return [
            'platform'    => 'linux',
            'baseboard'   => self::normalize($machineId),
            'bios_uuid'   => self::normalize($biosUuid),
            'cpu_id'      => self::normalize(php_uname('m')),
            'os_guid'     => self::normalize(gethostname() ?: 'LINUX-HOST'),
            'is_fallback' => false,
        ];
    }

    /**
     * Detects dummy, OEM placeholder, or zero-entropy strings.
     */
    public static function isPlaceholderOrLowEntropy(string $val): bool
    {
        $val = trim($val);
        if (strlen($val) < 3) {
            return true;
        }

        $upper = strtoupper($val);

        $dummyPatterns = [
            'TO BE FILLED',
            'DEFAULT STRING',
            'O.E.M',
            'OEM',
            'NOT APPLICABLE',
            'NOT SPECIFIED',
            'SYSTEM SERIAL',
            'BASE BOARD',
            'CHASSIS SERIAL',
            'IDENTIFYINGNUMBER',
            'UNKNOWN',
            'NONE',
            'NULL',
        ];
        foreach ($dummyPatterns as $pattern) {
            if (str_contains($upper, $pattern)) {
                return true;
            }
        }

        // Monotonous or dummy UUIDs
        if (preg_match('/^(00000000-0000-0000-0000-000000000000|FFFFFFFF-FFFF-FFFF-FFFF-FFFFFFFFFFFF|03000200-0400-0500-0006-000700080009)$/i', $upper)) {
            return true;
        }

        // Monotonous repeating characters (e.g., "00000000", "--------")
        if (preg_match('/^(.)\1+$/', $upper)) {
            return true;
        }

        return false;
    }

    /**
     * Normalizes a hardware identifier string.
     */
    public static function normalize(string $val): string
    {
        $val = trim($val);
        $val = strtoupper($val);
        if (self::isPlaceholderOrLowEntropy($val)) {
            return '';
        }
        return $val;
    }

    /**
     * Formats 16 hex chars into SizarDev-POS-XXXX-XXXX-XXXX-XXXX
     */
    public static function formatMachineId(string $sha256Hex): string
    {
        $short = substr(strtoupper($sha256Hex), 0, 16);
        return sprintf(
            'SizarDev-POS-%s-%s-%s-%s',
            substr($short, 0, 4),
            substr($short, 4, 4),
            substr($short, 8, 4),
            substr($short, 12, 4)
        );
    }

    /**
     * Normalizes any machine ID (legacy POS- or modern SizarDev-POS-) to canonical SizarDev-POS- format.
     */
    public static function normalizeMachineId(string $id): string
    {
        $id = strtoupper(trim($id));
        if (preg_match('/^(?:SIZARDEV-)?(?:POS-)?([A-F0-9]{4}-[A-F0-9]{4}-[A-F0-9]{4}-[A-F0-9]{4})$/i', $id, $m)) {
            return 'SizarDev-POS-' . strtoupper($m[1]);
        }
        return $id;
    }
}

